import{_ as l,a0 as s,w as t,s as u,ao as r,I as n,x as e,a1 as d,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160531 Linux vs. Windows device driver model","title":"Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較","tag":"201611","desc":""},"relativePath":"201611/20160531 Linux vs. Windows device driver model.md","filePath":"[post].md"}'),p={name:"201611/20160531 Linux vs. Windows device driver model.md"};function x(w,i,m,L,h,W){const o=s("Link");return t(),u("div",null,[i[24]||(i[24]=r('<h1 id="linux-與-windows-的設備驅動模型比對-架構、api-和開發環境比較" tabindex="-1">Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較 <a class="header-anchor" href="#linux-與-windows-的設備驅動模型比對-架構、api-和開發環境比較" aria-label="Permalink to “Linux 與 Windows 的設備驅動模型比對：架構、API 和開發環境比較”">​</a></h1><blockquote><p>名詞縮寫：</p><ul><li>API 應用程序接口（Application Program Interface ）</li><li>ABI 應用系統二進制接口（Application Binary Interface）</li></ul></blockquote><p>設備驅動是操作系統的一部分，它能夠通過一些特定的編程接口便於硬件設備的使用，這樣軟件就可以控制並且運行那些設備了。因為每個驅動都對應不同的操作系統，所以你就需要不同的 Linux、Windows 或 Unix 設備驅動，以便能夠在不同的計算機上使用你的設備。這就是為什麼當你僱傭一個驅動開發者或者選擇一個研發服務商提供者的時候，查看他們為各種操作系統平台開發驅動的經驗是非常重要的。</p><p><img src="https://c2.staticflickr.com/8/7289/26775594584_d2fe7483f9_c.jpg" alt=""></p><p>驅動開發的第一步是理解每個操作系統處理它的驅動的不同方式、底層驅動模型、它使用的架構、以及可用的開發工具。例如，Linux 驅動程序模型就與 Windows 非常不同。雖然 Windows 提倡驅動程序開發和操作系統開發分別進行，並通過一組 ABI 調用來結合驅動程序和操作系統，但是 Linux 設備驅動程序開發不依賴任何穩定的 ABI 或 API，所以它的驅動代碼並沒有被納入內核中。每一種模型都有自己的優點和缺點，但是如果你想為你的設備提供全面支持，那麼重要的是要全面的瞭解它們。</p><p>在本文中，我們將比較 Windows 和 Linux 設備驅動程序，探索不同的架構，API，構建開發和分發，希望讓您比較深入的理解如何開始為每一個操作系統編寫設備驅動程序。</p><h3 id="_1-設備驅動架構" tabindex="-1">1. 設備驅動架構 <a class="header-anchor" href="#_1-設備驅動架構" aria-label="Permalink to “1. 設備驅動架構”">​</a></h3><p>Windows 設備驅動程序的體系結構和 Linux 中使用的不同，它們各有優缺點。差異主要受以下原因的影響：Windows 是閉源操作系統，而 Linux 是開源操作系統。比較 Linux 和 Windows 設備驅動程序架構將幫助我們理解 Windows 和 Linux 驅動程序背後的核心差異。</p><h4 id="_1-1-windows-驅動架構" tabindex="-1">1.1. Windows 驅動架構 <a class="header-anchor" href="#_1-1-windows-驅動架構" aria-label="Permalink to “1.1. Windows 驅動架構”">​</a></h4><p>雖然 Linux 內核分發時帶着 Linux 驅動，而 Windows 內核則不包括設備驅動程序。與之不同的是，現代 Windows 設備驅動程序編寫使用 Windows 驅動模型（WDM），這是一種完全支持即插即用和電源管理的模型，所以可以根據需要加載和卸載驅動程序。</p><p>處理來自應用的請求，是由 Windows 內核的中被稱為 I/O 管理器的部分來完成的。I/O 管理器的作用是是轉換這些請求到 I/O 請求數據包（IO Request Packets）（IRP），IRP 可以被用來在驅動層識別請求並且傳輸數據。</p><p>Windows 驅動模型 WDM 提供三種驅動， 它們形成了三個層：</p><ul><li>過濾（Filter）驅動提供關於 IRP 的可選附加處理。</li><li>功能（Function）驅動是實現接口和每個設備通信的主要驅動。</li><li>總線（Bus）驅動服務不同的配適器和不同的總線控制器，來實現主機模式控制設備。</li></ul><p>一個 IRP 通過這些層就像它們經過 I/O 管理器到達底層硬件那樣。每個層能夠獨立的處理一個 IRP 並且把它們送回 I/O 管理器。在硬件底層中有硬件抽象層（HAL），它提供一個通用的接口到物理設備。</p><h4 id="_1-2-linux-驅動架構" tabindex="-1">1.2. Linux 驅動架構 <a class="header-anchor" href="#_1-2-linux-驅動架構" aria-label="Permalink to “1.2. Linux 驅動架構”">​</a></h4><p>相比於 Windows 設備驅動，Linux 設備驅動架構根本性的不同就是 Linux 沒有一個標準的驅動模型也沒有一個乾淨分隔的層。每一個設備驅動都被當做一個能夠自動的從內核中加載和卸載的模組來實現。Linux 為即插即用設備和電源管理設備提供一些方式，以便那些驅動可以使用它們來正確地管理這些設備，但這並不是必須的。</p><p>模式輸出那些它們提供的函數，並通過調用這些函數和傳入隨意定義的數據結構來溝通。請求來自文件系統或網絡層的用户應用，並被轉化為需要的數據結構。模組能夠按層堆疊，在一個模組進行處理之後，另外一個再處理，有些模組提供了對一類設備的公共調用接口，例如 USB 設備。</p><p>Linux 設備驅動程序支持三種設備：</p><ul><li>實現一個字節流接口的字符（Character）設備。</li><li>用於存放文件系統和處理多字節數據塊 IO 的塊（Block）設備。</li><li>用於通過網絡傳輸數據包的網絡（Network）接口。</li></ul><p>Linux 也有一個硬件抽象層（HAL），它實際扮演了物理硬件的設備驅動接口。</p><h3 id="_2-設備驅動-api" tabindex="-1">2. 設備驅動 API <a class="header-anchor" href="#_2-設備驅動-api" aria-label="Permalink to “2. 設備驅動 API”">​</a></h3><p>Linux 和 Windows 驅動 API 都屬於事件驅動類型：只有當某些事件發生的時候，驅動代碼才執行——當用户的應用程序希望從設備獲取一些東西，或者當設備有某些請求需要告知操作系統。</p><h4 id="_2-1-初始化" tabindex="-1">2.1. 初始化 <a class="header-anchor" href="#_2-1-初始化" aria-label="Permalink to “2.1. 初始化”">​</a></h4><p>在 Windows 上，驅動被表示為 <code>DriverObject</code> 結構，它在 <code>DriverEntry</code> 函數的執行過程中被初始化。這些入口點也註冊一些回調函數，用來響應設備的添加和移除、驅動卸載和處理新進入的 IRP。當一個設備連接的時候，Windows 創建一個設備對象，這個設備對象在設備驅動後面處理所有應用請求。</p><p>相比於 Windows，Linux 設備驅動生命週期由內核模組的 <code>module_init</code> 和 <code>module_exit</code> 函數負責管理，它們分別用於模組的加載和卸載。它們負責註冊模組來通過使用內核接口來處理設備的請求。這個模組需要創建一個設備文件（或者一個網絡接口），為其所希望管理的設備指定一個數字識別號，並註冊一些當用户與設備文件交互的時候所使用的回調函數。</p><h4 id="_2-2-命名和聲明設備" tabindex="-1">2.2. 命名和聲明設備 <a class="header-anchor" href="#_2-2-命名和聲明設備" aria-label="Permalink to “2.2. 命名和聲明設備”">​</a></h4><h5 id="在-windows-上註冊設備" tabindex="-1">在 Windows 上註冊設備 <a class="header-anchor" href="#在-windows-上註冊設備" aria-label="Permalink to “在 Windows 上註冊設備”">​</a></h5><p>Windows 設備驅動在新連接設備時是由回調函數 <code>AddDevice</code> 通知的。它接下來就去創建一個設備對象（device object），用於識別該設備的特定的驅動實例。取決於驅動的類型，設備對象可以是物理設備對象（Physical Device Object）（PDO），功能設備對象（Function Device Object）（FDO），或者過濾設備對象（Filter Device Object ）（FIDO）。設備對象能夠堆疊，PDO 在底層。</p><p>設備對象在這個設備連接在計算機期間一直存在。<code>DeviceExtension</code> 結構能夠被用於關聯到一個設備對象的全局數據。</p><p>設備對象可以有如下形式的名字 <code>\\Device\\DeviceName</code>，這被系統用來識別和定位它們。應用可以使用 <code>CreateFile</code> API 函數來打開一個有上述名字的文件，獲得一個可以用於和設備交互的句柄。</p><p>然而，通常只有 PDO 有自己的名字。未命名的設備能夠通過設備級接口來訪問。設備驅動註冊一個或多個接口，以 128 位全局唯一標識符（GUID）來標示它們。用户應用能夠使用已知的 GUID 來獲取一個設備的句柄。</p><h5 id="在-linux-上註冊設備" tabindex="-1">在 Linux 上註冊設備 <a class="header-anchor" href="#在-linux-上註冊設備" aria-label="Permalink to “在 Linux 上註冊設備”">​</a></h5><p>在 Linux 平台上，用户應用通過文件系統入口訪問設備，它通常位於 <code>/dev</code> 目錄。在模組初始化的時候，它通過調用內核函數 <code>register_chrdev</code> 創建了所有需要的入口。應用可以發起 <code>open</code> 系統調用來獲取一個文件描述符來與設備進行交互。這個調用後來被髮送到回調函數，這個調用（以及將來對該返回的文件描述符的進一步調用，例如 <code>read</code>、<code>write</code> 或<code>close</code>）會被分配到由該模組安裝到 <code>file_operations</code> 或者 <code>block_device_operations</code>這樣的數據結構中的回調函數。</p><p>設備驅動模組負責分配和保持任何需要用於操作的數據結構。傳送進文件系統回調函數的 <code>file</code> 結構有一個 <code>private_data</code> 字段，它可以被用來存放指向具體驅動數據的指針。塊設備和網絡接口 API 也提供類似的字段。</p><p>雖然應用使用文件系統的節點來定位設備，但是 Linux 在內部使用一個主設備號（major numbers）和次設備號（minor numbers）的概念來識別設備及其驅動。主設備號被用來識別設備驅動，而次設備號由驅動使用來識別它所管理的設備。驅動為了去管理一個或多個固定的主設備號，必須首先註冊自己或者讓系統來分配未使用的設備號給它。</p><p>目前，Linux 為主次設備對（major-minor pairs）使用一個 32 位的值，其中 12 位分配主設備號，並允許多達 4096 個不同的設備。主次設備對對於字符設備和塊設備是不同的，所以一個字符設備和一個塊設備能使用相同的設備對而不導致衝突。網絡接口是通過像 eth0 的符號名來識別，這些又是區別於主次設備的字符設備和塊設備的。</p><h4 id="_2-3-交換數據" tabindex="-1">2.3. 交換數據 <a class="header-anchor" href="#_2-3-交換數據" aria-label="Permalink to “2.3. 交換數據”">​</a></h4><p>Linux 和 Windows 都支持在用户級應用程序和內核級驅動程序之間傳輸數據的三種方式：</p><ul><li><strong>緩衝型輸入輸出（Buffered Input-Output）</strong> 它使用由內核管理的緩衝區。對於寫操作，內核從用户空間緩衝區中拷貝數據到內核分配的緩衝區，並且把它傳送到設備驅動中。讀操作也一樣，由內核將數據從內核緩衝區中拷貝到應用提供的緩衝區中。</li><li><strong>直接型輸入輸出（Direct Input-Output）</strong> 它不使用拷貝功能。代替它的是，內核在物理內存中釘死一塊用户分配的緩衝區以便它可以一直留在那裏，以便在數據傳輸過程中不被交換出去。</li><li><strong>內存映射（Memory mapping）</strong> 它也能夠由內核管理，這樣內核和用户空間應用就能夠通過不同的地址訪問同樣的內存頁。</li></ul><h5 id="windows-上的驅動程序-i-o-模式" tabindex="-1"><strong>Windows 上的驅動程序 I/O 模式</strong> <a class="header-anchor" href="#windows-上的驅動程序-i-o-模式" aria-label="Permalink to “Windows 上的驅動程序 I/O 模式”">​</a></h5><p>支持緩衝型 I/O 是 WDM 的內置功能。緩衝區能夠被設備驅動通過在 IRP 結構中的 <code>AssociatedIrp.SystemBuffer</code> 字段訪問。當需要和用户空間通訊的時候，驅動只需從這個緩衝區中進行讀寫操作。</p><p>Windows 上的直接 I/O 由內存描述符列表（memory descriptor lists）（MDL）介導。這種半透明的結構是通過在 IRP 中的 <code>MdlAddress</code> 字段來訪問的。它們被用來定位由用户應用程序分配的緩衝區的物理地址，並在 I/O 請求期間釘死不動。</p><p>在 Windows 上進行數據傳輸的第三個選項稱為 <code>METHOD_NEITHER</code>。 在這種情況下，內核需要傳送用户空間的輸入輸出緩衝區的虛擬地址給驅動，而不需要確定它們有效或者保證它們映射到一個可以由設備驅動訪問的物理內存地址。設備驅動負責處理這些數據傳輸的細節。</p><h5 id="linux-上的驅動程序-i-o-模式" tabindex="-1"><strong>Linux 上的驅動程序 I/O 模式</strong> <a class="header-anchor" href="#linux-上的驅動程序-i-o-模式" aria-label="Permalink to “Linux 上的驅動程序 I/O 模式”">​</a></h5><p>Linux 提供許多函數例如，<code>clear_user</code>、<code>copy_to_user</code>、<code>strncpy_from_user</code> 和一些其它的用來在內核和用户內存之間進行緩衝區數據傳輸的函數。這些函數保證了指向數據緩存區指針的有效，並且通過在內存區域之間安全地拷貝數據緩衝區來處理數據傳輸的所有細節。</p><p>然而，塊設備的驅動對已知大小的整個數據塊進行操作，它可以在內核和用户地址區域之間被快速移動而不需要拷貝它們。這種情況是由 Linux 內核來自動處理所有的塊設備驅動。塊請求隊列處理傳送數據塊而不用多餘的拷貝，而 Linux 系統調用接口來轉換文件系統請求到塊請求中。</p><p>最終，設備驅動能夠從內核地址區域分配一些存儲頁面（不可交換的）並且使用 <code>remap_pfn_range</code> 函數來直接映射這些頁面到用户進程的地址空間。然後應用能獲取這些緩衝區的虛擬地址並且使用它來和設備驅動交流。</p><h3 id="_3-設備驅動開發環境" tabindex="-1">3. 設備驅動開發環境 <a class="header-anchor" href="#_3-設備驅動開發環境" aria-label="Permalink to “3. 設備驅動開發環境”">​</a></h3><h4 id="_3-1-設備驅動框架" tabindex="-1">3.1. 設備驅動框架 <a class="header-anchor" href="#_3-1-設備驅動框架" aria-label="Permalink to “3.1. 設備驅動框架”">​</a></h4><h5 id="windows-驅動程序工具包" tabindex="-1">Windows 驅動程序工具包 <a class="header-anchor" href="#windows-驅動程序工具包" aria-label="Permalink to “Windows 驅動程序工具包”">​</a></h5><p>Windows 是一個閉源操作系統。Microsoft 提供 Windows 驅動程序工具包以方便非 Microsoft 供應商開發 Windows 設備驅動。工具包中包含開發、調試、檢驗和打包 Windows 設備驅動等所需的所有內容。</p><p>Windows 驅動模型（Windows Driver Model）（WDM）為設備驅動定義了一個乾淨的接口框架。Windows 保持這些接口的源代碼和二進制的兼容性。編譯好的 WDM 驅動通常是前向兼容性：也就是説，一個較舊的驅動能夠在沒有重新編譯的情況下在較新的系統上運行，但是它當然不能夠訪問系統提供的新功能。但是，驅動不保證後向兼容性。</p><h5 id="linux-源代碼" tabindex="-1"><strong>Linux 源代碼</strong> <a class="header-anchor" href="#linux-源代碼" aria-label="Permalink to “Linux 源代碼”">​</a></h5><p>和 Windows 相對比，Linux 是一個開源操作系統，因此 Linux 的整個源代碼是用於驅動開發的 SDK。沒有驅動設備的正式框架，但是 Linux 內核包含許多提供瞭如驅動註冊這樣的通用服務的子系統。這些子系統的接口在內核頭文件中描述。</p><p>儘管 Linux 有定義接口，但這些接口在設計上並不穩定。Linux 不提供有關前向和後向兼容的任何保證。設備驅動對於不同的內核版本需要重新編譯。沒有穩定性的保證可以讓 Linux 內核進行快速開發，因為開發人員不必去支持舊的接口，並且能夠使用最好的方法解決手頭的這些問題。</p><p>當為 Linux 寫樹內（in-tree）（指當前 Linux 內核開發主幹）驅動程序時，這種不斷變化的環境不會造成任何問題，因為它們作為內核源代碼的一部分，與內核本身同步更新。然而，閉源驅動必須單獨開發，並且在樹外（out-of-tree），必須維護它們以支持不同的內核版本。因此，Linux 鼓勵設備驅動程序開發人員在樹內維護他們的驅動。</p><h4 id="_3-2-為設備驅動構建系統" tabindex="-1">3.2. 為設備驅動構建系統 <a class="header-anchor" href="#_3-2-為設備驅動構建系統" aria-label="Permalink to “3.2. 為設備驅動構建系統”">​</a></h4><p>Windows 驅動程序工具包為 Microsoft Visual Studio 添加了驅動開發支持，並包括用來構建驅動程序代碼的編譯器。開發 Windows 設備驅動程序與在 IDE 中開發用户空間應用程序沒有太大的區別。Microsoft 提供了一個企業 Windows 驅動程序工具包，提供了類似於 Linux 命令列的構建環境。</p>',58)),n("p",null,[i[1]||(i[1]=e("Linux 使用 Makefile 作為樹內和樹外系統設備驅動程序的構建系統。Linux 構建系統非常發達，通常是一個設備驅動程序只需要少數行就產生一個可工作的二進制代碼。開發人員可以使用任何 ",-1)),d(o,{href:"https://linux.cn/article-7704-1.html"},{default:a(()=>[...i[0]||(i[0]=[e("IDE",-1)])]),_:1}),i[2]||(i[2]=e("，只要它可以處理 Linux 源代碼庫和運行 ",-1)),i[3]||(i[3]=n("code",null,"make",-1)),i[4]||(i[4]=e(" ，他們也可以很容易地從終端手動編譯驅動程序。",-1))]),i[25]||(i[25]=n("h4",{id:"_3-3-文檔支持",tabindex:"-1"},[e("3.3. 文檔支持 "),n("a",{class:"header-anchor",href:"#_3-3-文檔支持","aria-label":"Permalink to “3.3. 文檔支持”"},"​")],-1)),i[26]||(i[26]=n("p",null,"Windows 對於驅動程序的開發有良好的文檔支持。Windows 驅動程序工具包包括文檔和示例驅動程序代碼，通過 MSDN 可獲得關於內核接口的大量信息，並存在大量的有關驅動程序開發和 Windows 底層的參考和指南。",-1)),n("p",null,[i[6]||(i[6]=e("Linux 文檔不是描述性的，但整個 Linux 源代碼可供驅動開發人員使用緩解了這一問題。源代碼樹中的 Documentation 目錄描述了一些 Linux 的子系統，但是有",-1)),d(o,{href:"http://xmodulo.com/go/linux_device_driver_books"},{default:a(()=>[...i[5]||(i[5]=[e("幾本書",-1)])]),_:1}),i[7]||(i[7]=e("介紹了關於 Linux 設備驅動程序開發和 Linux 內核概覽，它們更詳細。",-1))]),i[27]||(i[27]=r('<p>Linux 沒有提供設備驅動程序的指定樣本，但現有生產級驅動程序的源代碼可用，可以用作開發新設備驅動程序的參考。</p><h4 id="_3-4-調試支持" tabindex="-1">3.4. 調試支持 <a class="header-anchor" href="#_3-4-調試支持" aria-label="Permalink to “3.4. 調試支持”">​</a></h4><p>Linux 和 Windows 都有可用於追蹤調試驅動程序代碼的日誌機制。在 Windows 上將使用 <code>DbgPrint</code> 函數，而在 Linux 上使用的函數稱為 <code>printk</code>。然而，並不是每個問題都可以通過只使用日誌記錄和源代碼來解決。有時斷點更有用，因為它們允許檢查驅動代碼的動態行為。交互式調試對於研究崩潰的原因也是必不可少的。</p><p>Windows 通過其內核級調試器 <code>WinDbg</code> 支持交互式調試。這需要通過一個串行端口連接兩台機器：一台計算機運行被調試的內核，另一台運行調試器和控制被調試的操作系統。Windows 驅動程序工具包包括 Windows 內核的調試符號，因此 Windows 的數據結構將在調試器中部分可見。</p><p>Linux 還支持通過 <code>KDB</code> 和 <code>KGDB</code> 進行的交互式調試。調試支持可以內置到內核，並可在啓動時啓用。之後，可以直接通過物理鍵盤調試系統，或通過串行端口從另一台計算機連接到它。KDB 提供了一個簡單的命令列界面，這是唯一的在同一台機器上來調試內核的方法。然而，KDB 缺乏源代碼級調試支持。KGDB 通過串行端口提供了一個更復雜的接口。它允許使用像 GDB 這樣標準的應用程序調試器來調試 Linux 內核，就像任何其它用户空間應用程序一樣。</p><h3 id="_4-設備驅動分發" tabindex="-1">4. 設備驅動分發 <a class="header-anchor" href="#_4-設備驅動分發" aria-label="Permalink to “4. 設備驅動分發”">​</a></h3><h5 id="_4-1-安裝設備驅動" tabindex="-1">4.1. 安裝設備驅動 <a class="header-anchor" href="#_4-1-安裝設備驅動" aria-label="Permalink to “4.1. 安裝設備驅動”">​</a></h5><p>在 Windows 上安裝的驅動程序，是由被稱為為 INF 的文本文件描述的，通常存儲在 <code>C:\\Windows\\INF</code> 目錄中。這些文件由驅動供應商提供，並且定義哪些設備由該驅動程序服務，哪裏可以找到驅動程序的二進制文件，和驅動程序的版本等。</p><p>當一個新設備插入計算機時，Windows 通過查看已經安裝的驅動程序並且選擇適當的一個加載。當設備被移除的時候，驅動會自動卸載它。</p><p>在 Linux 上，一些驅動被構建到內核中並且保持永久的加載。非必要的驅動被構建為內核模組，它們通常是存儲在 <code>/lib/modules/kernel-version</code> 目錄中。這個目錄還包含各種配置文件，如 <code>modules.dep</code>，用於描述內核模組之間的依賴關係。</p><p>雖然 Linux 內核可以在自身啓動時加載一些模組，但通常模組加載由用户空間應用程序監督。例如，<code>init</code> 進程可能在系統初始化期間加載一些模組，<code>udev</code> 守護程序負責跟蹤新插入的設備併為它們加載適當的模組。</p><h4 id="_4-2-更新設備驅動" tabindex="-1">4.2. 更新設備驅動 <a class="header-anchor" href="#_4-2-更新設備驅動" aria-label="Permalink to “4.2. 更新設備驅動”">​</a></h4><p>Windows 為設備驅動程序提供了穩定的二進制接口，因此在某些情況下，無需與系統一起更新驅動程序二進制文件。任何必要的更新由 Windows Update 服務處理，它負責定位、下載和安裝適用於系統的最新版本的驅動程序。</p>',13)),n("p",null,[i[9]||(i[9]=e("然而，Linux 不提供穩定的二進制接口，因此有必要在每次內核更新時重新編譯和更新所有必需的設備驅動程序。顯然，內置在內核中的設備驅動程序會自動更新，但是樹外模組會產生輕微的問題。 維護最新的模組二進制文件的任務通常用 ",-1)),d(o,{href:"http://xmodulo.com/build-kernel-module-dkms-linux.html"},{default:a(()=>[...i[8]||(i[8]=[e("DKMS",-1)])]),_:1}),i[10]||(i[10]=e(" 來解決：這是一個當安裝新的內核版本時自動重建所有註冊的內核模組的服務。",-1))]),i[28]||(i[28]=n("h4",{id:"_4-3-安全方面的考慮",tabindex:"-1"},[e("4.3. 安全方面的考慮 "),n("a",{class:"header-anchor",href:"#_4-3-安全方面的考慮","aria-label":"Permalink to “4.3. 安全方面的考慮”"},"​")],-1)),i[29]||(i[29]=n("p",null,"所有 Windows 設備驅動程序在 Windows 加載它們之前必須被數字簽名。在開發期間可以使用自簽名證書，但是分發給終端用户的驅動程序包必須使用 Microsoft 信任的有效證書進行簽名。供應商可以從 Microsoft 授權的任何受信任的證書頒發機構獲取軟件出版商證書（Software Publisher Certificate）。然後，此證書由 Microsoft 交叉簽名，並且生成的交叉證書用於在發行之前簽署驅動程序包。",-1)),i[30]||(i[30]=n("p",null,"Linux 內核也能配置為在內核模組被加載前校驗簽名，並禁止不可信的內核模組。被內核所信任的公鑰集在構建時是固定的，並且是完全可配置的。由內核執行的檢查，這個檢查嚴格性在構建時也是可配置的，範圍從簡單地為不可信模組發出警告，到拒絕加載有效性可疑的任何東西。",-1)),i[31]||(i[31]=n("h3",{id:"_5-結論",tabindex:"-1"},[e("5. 結論 "),n("a",{class:"header-anchor",href:"#_5-結論","aria-label":"Permalink to “5. 結論”"},"​")],-1)),i[32]||(i[32]=n("p",null,"如上所示，Windows 和 Linux 設備驅動程序基礎設施有一些共同點，例如調用 API 的方法，但更多的細節是相當不同的。最突出的差異源於 Windows 是由商業公司開發的封閉源操作系統這個事實。這使得 Windows 上有好的、文檔化的、穩定的驅動 ABI 和正式框架，而在 Linux 上，更多的是源代碼做了一個有益的補充。文檔支持也在 Windows 環境中更加發達，因為 Microsoft 具有維護它所需的資源。",-1)),i[33]||(i[33]=n("p",null,"另一方面，Linux 不會使用框架來限制設備驅動程序開發人員，並且內核和產品級設備驅動程序的源代碼可以在需要的時候有所幫助。缺乏接口穩定性也有其作用，因為它意味着最新的設備驅動程序總是使用最新的接口，內核本身承載較小的後向兼容性負擔，這帶來了更乾淨的代碼。",-1)),i[34]||(i[34]=n("p",null,"瞭解這些差異以及每個系統的具體情況是為您的設備提供有效的驅動程序開發和支持的關鍵的第一步。我們希望這篇文章對 Windows 和 Linux 設備驅動程序開發做的對比，有助於您理解它們，並在設備驅動程序開發過程的研究中，將此作為一個偉大的起點。",-1)),i[35]||(i[35]=n("hr",null,null,-1)),n("p",null,[i[12]||(i[12]=e("via: ",-1)),d(o,{href:"http://xmodulo.com/linux-vs-windows-device-driver-model.html"},{default:a(()=>[...i[11]||(i[11]=[e("http://xmodulo.com/linux-vs-windows-device-driver-model.html",-1)])]),_:1})]),n("p",null,[i[16]||(i[16]=e("作者：",-1)),d(o,{href:"http://xmodulo.com/author/dennis"},{default:a(()=>[...i[13]||(i[13]=[e("Dennis Turpitka",-1)])]),_:1}),i[17]||(i[17]=e(" 譯者：",-1)),d(o,{href:"https://github.com/FrankXinqi"},{default:a(()=>[...i[14]||(i[14]=[e("FrankXinqi &YangYang",-1)])]),_:1}),i[18]||(i[18]=e(" 校對：",-1)),d(o,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[e("wxy",-1)])]),_:1})]),n("p",null,[i[21]||(i[21]=e("本文由 ",-1)),d(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[19]||(i[19]=[e("LCTT",-1)])]),_:1}),i[22]||(i[22]=e(" 原創編譯，",-1)),d(o,{href:"https://linux.cn/"},{default:a(()=>[...i[20]||(i[20]=[e("Linux中國",-1)])]),_:1}),i[23]||(i[23]=e(" 榮譽推出",-1))])])}const P=l(p,[["render",x]]);export{b as __pageData,P as default};
